schema_ddl:
CREATE DOMAIN importo_premio AS NUMERIC(12,2) CHECK (VALUE > 0);

CREATE DOMAIN stato_polizza AS TEXT CHECK (VALUE IN ('attiva', 'sospesa', 'scaduta'));

CREATE TABLE polizze (
    id INT PRIMARY KEY,
    numero_polizza TEXT NOT NULL UNIQUE,
    tipo_polizza TEXT NOT NULL,
    regione TEXT NOT NULL,
    premio_annuo importo_premio NOT NULL,
    stato stato_polizza NOT NULL,
    data_emissione DATE NOT NULL,
    data_scadenza DATE NOT NULL,
    CHECK (data_scadenza > data_emissione)
);
